-- PHARMALINK SUITE - A executer apres les scripts existants
alter table public.medicines add column if not exists laboratory text;
alter table public.medicines add column if not exists source text not null default 'pharmacy';
alter table public.medicines add column if not exists verification_status text not null default 'pending';
alter table public.pharmacies add column if not exists email text; alter table public.pharmacies add column if not exists postal_code text; alter table public.pharmacies add column if not exists verification_status text not null default 'pending';
create or replace function public.register_my_pharmacy(p_name text,p_license_number text,p_address text,p_city text,p_governorate text,p_phone text,p_email text default null,p_postal_code text default null) returns uuid language plpgsql security definer set search_path=public as $$declare u uuid:=auth.uid();p uuid;begin if u is null then raise exception 'Connexion requise';end if;if exists(select 1 from pharmacy_members where user_id=u and is_active) then raise exception 'Compte deja rattache';end if;insert into pharmacies(name,license_number,address,city,governorate,phone,email,postal_code,is_verified,is_active,verification_status) values(trim(p_name),trim(p_license_number),trim(p_address),trim(p_city),trim(p_governorate),trim(p_phone),nullif(trim(p_email),''),nullif(trim(p_postal_code),''),false,true,'pending') returning id into p;insert into pharmacy_members(pharmacy_id,user_id,role,is_active) values(p,u,'owner',true);return p;end$$;
grant execute on function public.register_my_pharmacy(text,text,text,text,text,text,text,text) to authenticated;
create or replace function public.create_or_get_medicine(p_commercial_name text,p_dci text default null,p_dosage text default null,p_form text default null,p_barcode text default null,p_laboratory text default null) returns uuid language plpgsql security definer set search_path=public as $$declare m uuid;begin if auth.uid() is null then raise exception 'Connexion requise';end if;select id into m from medicines where (p_barcode is not null and barcode=p_barcode) or (lower(trim(commercial_name))=lower(trim(p_commercial_name)) and coalesce(lower(trim(dosage)),'')=coalesce(lower(trim(p_dosage)),'')) limit 1;if m is null then insert into medicines(commercial_name,dci,dosage,form,barcode,laboratory,source,verification_status,is_active) values(trim(p_commercial_name),nullif(trim(p_dci),''),nullif(trim(p_dosage),''),nullif(trim(p_form),''),nullif(trim(p_barcode),''),nullif(trim(p_laboratory),''),'pharmacy','pending',true) returning id into m;end if;return m;end$$;
grant execute on function public.create_or_get_medicine(text,text,text,text,text,text) to authenticated;
create or replace function public.pharmacy_stock_insights(p_pharmacy_id uuid) returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('summary',format('%s stock(s) faible(s), %s lot(s) expirant sous 90 jours. Vérifiez les seuils et appliquez une rotation FEFO.',count(*) filter(where quantity<=low_stock_threshold),count(*) filter(where expiry_date between current_date and current_date+90))) from inventory_items where pharmacy_id=p_pharmacy_id and is_pharmacy_member(p_pharmacy_id)$$;
grant execute on function public.pharmacy_stock_insights(uuid) to authenticated;
-- Public search already filters p.is_verified=true. Quantities stay private.
grant execute on function public.search_medicine_availability(text,text) to anon,authenticated;
do $$ begin alter publication supabase_realtime add table public.inventory_items; exception when duplicate_object then null; end $$;
notify pgrst,'reload schema';